turtle.raw:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix schema: <http://schema.org/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix dash: <http://datashapes.org/dash#> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .
@prefix vcard: <http://www.w3.org/2006/vcard/ns#> .
@prefix ex: <http://example.com/> .

# Parameter-shapes voor jaarwaarde. De parameter biedt de gebruiker éém selectieveld voor het jaar. 
ex:YearValuePickList
    a sh:NodeShape ;
    sh:targetClass ex:YearValuePickList ;
    rdfs:label "Jaarwaarden" ;
    rdfs:comment "Een shape met één eigenschap: om een keuzelijstveld te creëren waarmee de gebruiker met handmatige invoer het jaar kan specificeren."@nl ;
    sh:property [
          sh:path ex:jaar ;
          sh:name "jaar";
          sh:description "Handmatige invoer van de jaarwaarde."@nl ;
          sh:maxCount 1 ;
          sh:minCount 1 ;
          sh:datatype xsd:gYear ;
          sh:maxInclusive "2026"^^xsd:gYear ;
          sh:minInclusive "2024"^^xsd:gYear ;
      ]
.

